import React, { useCallback, useMemo, useState } from 'react';
import {
  Button,
  Select,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  LinPageLayout,
  useCatalogTableBusy,
  type LinListToolbarActionDef,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { analyticsService } from '../../../services/analytics/analyticsService';
import type { PlanVsActualBudgetRow } from '../../../services/analytics/models';
import { formatDate, formatVnd } from '../../../utils/formatters';
import { exportExcel, MONTH_OPTIONS } from '../../../utils/exportExcel';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import erp from '../../../styles/erpPage.module.css';
import reportStyles from '../../../styles/erpReportPage.module.css';
import styles from './PhanTichKeHoachThucHienPage.module.css';

const TEST_ID = 'erp-plan-vs-actual-budget';
const PAGE_ID = 'baocao-phan-tich-ke-hoach-thuc-hien';
const TITLE = 'Báo cáo phân tích kế hoạch và thực hiện';

const TEMPLATE_OPTIONS = [
  { value: 'GLKHNS_CP', label: 'GLKHNS_CP — Ngân sách' },
  { value: 'GLKHNS_DT', label: 'GLKHNS_DT — Doanh thu' },
  { value: 'GLKHNS_KQ', label: 'GLKHNS_KQ — KQSXKD' },
];

type RowTag = 'Leaf' | 'Formula' | 'Section';

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function currentYear(): number {
  return new Date().getFullYear();
}

function yearOptions(): { value: string; label: string }[] {
  const y = currentYear();
  const list: { value: string; label: string }[] = [];
  for (let i = y + 1; i >= y - 10; i -= 1) {
    list.push({ value: String(i), label: String(i) });
  }
  return list;
}

function mapRowTag(raw: PlanVsActualBudgetRow['rowTag'], isFormula?: boolean): RowTag {
  if (raw === 'Formula' || isFormula) return 'Formula';
  if (raw === 'Section' || raw === 'Chrome') return 'Section';
  return 'Leaf';
}

function normalizeItems(items: PlanVsActualBudgetRow[]): PlanVsActualBudgetRow[] {
  return items.map(r => {
    const rowTag = mapRowTag(r.rowTag, r.isFormula);
    const isFormula = rowTag === 'Formula' || Boolean(r.isFormula);
    return {
      ...r,
      rowTag,
      isFormula,
      isBold: Boolean(r.isBold) || isFormula,
      lineCode: r.lineCode ?? '',
      indicatorName: r.indicatorName ?? '',
      actualAmount: Number(r.actualAmount ?? 0),
      planAmount: Number(r.planAmount ?? 0),
      actualYtd: Number(r.actualYtd ?? 0),
      planYtd: Number(r.planYtd ?? 0),
      debitAccountFormula: r.debitAccountFormula ?? '',
      creditAccountFormula: r.creditAccountFormula ?? '',
      calcFormula: r.calcFormula ?? '',
      sortStt: Number(r.sortStt ?? 0),
    };
  });
}

function rowClassName(row: PlanVsActualBudgetRow): string {
  const tag = mapRowTag(row.rowTag, row.isFormula);
  const parts: string[] = [];
  if (tag === 'Formula') parts.push(styles.rowToneFormula);
  if (tag === 'Section') parts.push(styles.rowToneSection);
  if (row.isBold) parts.push(styles.rowBold);
  return parts.join(' ');
}

function pad2(n: number): string {
  return String(n).padStart(2, '0');
}

const PhanTichKeHoachThucHienPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const years = useMemo(() => yearOptions(), []);

  const [fromMonth, setFromMonth] = useState('1');
  const [toMonth, setToMonth] = useState('12');
  const [year, setYear] = useState(String(currentYear()));
  const [templateCode, setTemplateCode] = useState('GLKHNS_CP');

  const [items, setItems] = useState<PlanVsActualBudgetRow[]>([]);
  const [appliedFromMonth, setAppliedFromMonth] = useState(1);
  const [appliedToMonth, setAppliedToMonth] = useState(12);
  const [appliedYear, setAppliedYear] = useState(currentYear());
  const [appliedTemplateCode, setAppliedTemplateCode] = useState('GLKHNS_CP');
  const [captionText, setCaptionText] = useState('');
  const [masterTitle1, setMasterTitle1] = useState('');
  const [metaFromDate, setMetaFromDate] = useState('');
  const [metaToDate, setMetaToDate] = useState('');
  const [hasViewed, setHasViewed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [filterError, setFilterError] = useState('');
  const { showTableLoading } = useCatalogTableBusy(loading);

  const handleView = useCallback(() => {
    setFilterError('');
    const company = sessionCompany();
    if (!company) {
      setFilterError('Không xác định đơn vị');
      dispatchAppToast(dispatch, { message: 'Không xác định đơn vị', type: 'error' });
      return;
    }

    const fm = Number(fromMonth);
    const tm = Number(toMonth);
    const y = Number(year);
    const tpl = (templateCode || '').trim();

    if (!Number.isInteger(fm) || fm < 1 || fm > 12) {
      setFilterError('Chọn tháng từ');
      dispatchAppToast(dispatch, { message: 'Chọn tháng từ', type: 'error' });
      return;
    }
    if (!Number.isInteger(tm) || tm < 1 || tm > 12) {
      setFilterError('Chọn tháng đến');
      dispatchAppToast(dispatch, { message: 'Chọn tháng đến', type: 'error' });
      return;
    }
    if (!Number.isInteger(y) || y < 1900 || y > 2100) {
      setFilterError('Chọn năm');
      dispatchAppToast(dispatch, { message: 'Chọn năm', type: 'error' });
      return;
    }
    if (fm > tm) {
      setFilterError('Tháng từ phải ≤ tháng đến');
      dispatchAppToast(dispatch, { message: 'Tháng từ phải ≤ tháng đến', type: 'error' });
      return;
    }
    if (!['GLKHNS_CP', 'GLKHNS_DT', 'GLKHNS_KQ'].includes(tpl)) {
      setFilterError('Chọn mẫu báo cáo');
      dispatchAppToast(dispatch, { message: 'Chọn mẫu báo cáo', type: 'error' });
      return;
    }

    setLoading(true);
    analyticsService
      .getPlanVsActualBudget({
        fromMonth: fm,
        toMonth: tm,
        year: y,
        templateCode: tpl,
        pageSize: 0,
      })
      .then(report => {
        setItems(normalizeItems(report.items ?? []));
        setAppliedFromMonth(fm);
        setAppliedToMonth(tm);
        setAppliedYear(y);
        setAppliedTemplateCode(tpl);
        const meta = report.meta;
        setCaptionText((meta?.captionText || '').trim());
        setMasterTitle1((meta?.masterTitle1 || '').trim());
        setMetaFromDate((meta?.fromDate || '').toString().slice(0, 10));
        setMetaToDate((meta?.toDate || '').toString().slice(0, 10));
        setHasViewed(true);
      })
      .catch(err => {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được báo cáo phân tích kế hoạch và thực hiện'),
          type: 'error',
        });
      })
      .finally(() => setLoading(false));
  }, [dispatch, fromMonth, toMonth, year, templateCode]);

  const onEnterView = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleView();
      }
    },
    [handleView],
  );

  const handleRefresh = useCallback(() => {
    setFromMonth('1');
    setToMonth('12');
    setYear(String(currentYear()));
    setTemplateCode('GLKHNS_CP');
    setFilterError('');
  }, []);

  const handleExport = useCallback(() => {
    if (!hasViewed || loading) return;
    void exportExcel(
      '/accounting/plan-vs-actual-budget/export-excel',
      {
        fromMonth: appliedFromMonth,
        toMonth: appliedToMonth,
        year: appliedYear,
        templateCode: appliedTemplateCode,
        pageSize: 0,
      },
      `phan-tich-ke-hoach-thuc-hien_${appliedFromMonth}_${appliedToMonth}_${appliedYear}_${appliedTemplateCode}.xlsx`,
    ).catch(() => {
      /* toast already in exportExcel */
    });
  }, [appliedFromMonth, appliedToMonth, appliedYear, appliedTemplateCode, hasViewed, loading]);

  const handlePrint = useCallback(() => {
    if (!hasViewed) return;
    window.print();
  }, [hasViewed]);

  const toolbarActions = useMemo<LinListToolbarActionDef[]>(
    () => [
      {
        id: 'refresh',
        action: 'refresh',
        placement: 'left',
        label: 'Làm mới',
        variant: 'secondary',
        testId: `${TEST_ID}-toolbar-refresh-btn`,
        disabled: loading,
        onClick: handleRefresh,
      },
      {
        id: 'export-excel',
        action: 'exportExcel',
        placement: 'left',
        label: 'Xuất Excel',
        variant: 'secondary',
        testId: `${TEST_ID}-export-excel`,
        disabled: !hasViewed || loading,
        onClick: handleExport,
      },
      {
        id: 'print',
        action: 'print',
        placement: 'left',
        label: 'In',
        variant: 'secondary',
        testId: `${TEST_ID}-export-print`,
        disabled: !hasViewed || loading,
        onClick: handlePrint,
      },
    ],
    [handleExport, handlePrint, handleRefresh, hasViewed, loading],
  );

  const subtitle = hasViewed
    ? (() => {
        const base =
          captionText ||
          `Từ tháng ${pad2(appliedFromMonth)} đến tháng ${pad2(appliedToMonth)} năm ${appliedYear}`;
        if (metaFromDate && metaToDate) {
          return `${base} · ${formatDate(metaFromDate)} – ${formatDate(metaToDate)}`;
        }
        return base;
      })()
    : '';

  const allMoneyZero =
    hasViewed &&
    items.every(
      r =>
        Number(r.actualAmount ?? 0) === 0 &&
        Number(r.planAmount ?? 0) === 0 &&
        Number(r.actualYtd ?? 0) === 0 &&
        Number(r.planYtd ?? 0) === 0,
    );

  const grid = (
    <div>
      {masterTitle1 ? (
        <div className={styles.masterTitle} data-testid={`${TEST_ID}-master-title`}>
          {masterTitle1}
        </div>
      ) : null}
      {subtitle ? (
        <div className={styles.subtitle} data-testid={`${TEST_ID}-subtitle`}>
          {subtitle}
        </div>
      ) : null}
      {!hasViewed && !loading ? (
        <div className={styles.hint} data-testid={`${TEST_ID}-hint`}>
          Chọn tháng từ–đến, năm, mẫu báo cáo và bấm Xem
        </div>
      ) : null}
      <table className={reportStyles.table} data-testid={`${TEST_ID}-grid`}>
        <thead>
          <tr>
            <th>Chỉ tiêu</th>
            <th className={reportStyles.colRight}>Thực hiện</th>
            <th className={reportStyles.colRight}>Kế hoạch</th>
            <th className={reportStyles.colRight}>Thực hiện LK</th>
            <th className={reportStyles.colRight}>Kế hoạch LK</th>
          </tr>
        </thead>
        <tbody>
          {items.map((row, index) => {
            const tag = mapRowTag(row.rowTag, row.isFormula);
            return (
              <tr
                key={`${row.lineCode}|${row.sortStt ?? ''}|${index}`}
                className={rowClassName(row)}
                data-testid={`${TEST_ID}-row-${index}`}
                data-row-tag={tag}
                data-is-formula={row.isFormula ? '1' : '0'}
                data-is-bold={row.isBold ? '1' : '0'}
                data-line-code={row.lineCode ?? ''}
              >
                <td>{row.indicatorName}</td>
                <td className={reportStyles.colRight}>{formatVnd(row.actualAmount)}</td>
                <td className={reportStyles.colRight}>{formatVnd(row.planAmount)}</td>
                <td className={reportStyles.colRight}>{formatVnd(row.actualYtd)}</td>
                <td className={reportStyles.colRight}>{formatVnd(row.planYtd)}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
      {allMoneyZero ? (
        <div className={erp.empty} data-testid={`${TEST_ID}-empty`}>
          Không có dữ liệu
        </div>
      ) : null}
    </div>
  );

  return (
    <div
      className={erp.voucherListRoot}
      data-catalog-list-page
      data-report-list-page
      data-testid={`${TEST_ID}-list`}
    >
      <LinPageLayout
        kind="report"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{ title: TITLE, titleIconClass: 'fas fa-chart-bar' }}
        listTitle={TITLE}
        filterMaxWidthPx={1200}
        showTableLoading={showTableLoading}
        skeletonRows={8}
        toolbarProps={{
          testIdPrefix: TEST_ID,
          profile: 'report',
          actions: toolbarActions,
        }}
        filters={(
          <>
            <div data-testid={`${TEST_ID}-field-fromMonth`} onKeyDown={onEnterView}>
              <Select
                label="Từ tháng"
                value={fromMonth}
                onChange={e => setFromMonth(e.target.value)}
                options={MONTH_OPTIONS}
                size="small"
              />
            </div>
            <div data-testid={`${TEST_ID}-field-toMonth`} onKeyDown={onEnterView}>
              <Select
                label="Đến tháng"
                value={toMonth}
                onChange={e => setToMonth(e.target.value)}
                options={MONTH_OPTIONS}
                size="small"
              />
            </div>
            <div data-testid={`${TEST_ID}-field-year`} onKeyDown={onEnterView}>
              <Select
                label="Năm"
                value={year}
                onChange={e => setYear(e.target.value)}
                options={years}
                size="small"
              />
            </div>
            <div data-testid={`${TEST_ID}-field-templateCode`} onKeyDown={onEnterView}>
              <Select
                label="Mẫu báo cáo"
                value={templateCode}
                onChange={e => setTemplateCode(e.target.value)}
                options={TEMPLATE_OPTIONS}
                size="small"
              />
            </div>
            <Button
              variant="primary"
              onClick={handleView}
              disabled={loading}
              data-testid={`${TEST_ID}-view-btn`}
            >
              Xem
            </Button>
            {filterError ? (
              <div data-testid={`${TEST_ID}-filter-error`}>{filterError}</div>
            ) : null}
          </>
        )}
      >
        {grid}
      </LinPageLayout>
    </div>
  );
};

export default PhanTichKeHoachThucHienPage;
